      draw: `function(ctx,tc,dt,W,H,LINES,CS){ctx.clearRect(0,0,W,H);var bg=ctx.createRadialGradient(W*0.5,H*0.5,0,W*0.5,H*0.5,W*0.8);bg.addColorStop(0,'#04011a');bg.addColorStop(0.5,'#020110');bg.addColorStop(1,'#000008');ctx.fillStyle=bg;ctx.fillRect(0,0,W,H);nebs.forEach(function(n){var g=ctx.createRadialGradient(n.cx+Math.sin(tc*0.2)*20,n.cy+Math.cos(tc*0.15)*15,0,n.cx,n.cy,Math.max(n.rx,n.ry));g.addColorStop(0,n.c);g.addColorStop(1,'transparent');ctx.save();ctx.scale(1,n.ry/n.rx);ctx.fillStyle=g;ctx.beginPath();ctx.arc(n.cx,n.cy*(n.rx/n.ry),n.rx,0,Math.PI*2);ctx.fill();ctx.restore();});var pulse=0.6+0.4*Math.sin(tc*1.2);for(var ring=5;ring>=1;ring--){var rr=wh.r*(ring/5)*pulse;var g2=ctx.createRadialGradient(wh.cx,wh.cy,0,wh.cx,wh.cy,rr);g2.addColorStop(0,'rgba(180,100,255,'+(0.12*ring)+')');g2.addColorStop(0.6,'rgba(80,20,180,'+(0.06*ring)+')');g2.addColorStop(1,'transparent');ctx.fillStyle=g2;ctx.beginPath();ctx.arc(wh.cx,wh.cy,rr,0,Math.PI*2);ctx.fill();}ctx.save();ctx.strokeStyle='rgba(200,120,255,'+(0.5*pulse)+')';ctx.lineWidth=2;ctx.shadowColor='rgba(200,120,255,.8)';ctx.shadowBlur=18*pulse;ctx.beginPath();ctx.arc(wh.cx,wh.cy,wh.r*pulse,0,Math.PI*2);ctx.stroke();ctx.restore();stars.forEach(function(s){s.phase+=s.spd*dt;var b=0.4+0.6*Math.abs(Math.sin(s.phase));ctx.save();ctx.globalAlpha=b;ctx.fillStyle=s.col;ctx.shadowColor=s.col;ctx.shadowBlur=s.r>1.2?8:3;ctx.beginPath();ctx.arc(s.x,s.y,s.r,0,Math.PI*2);ctx.fill();ctx.restore();});shoots.forEach(function(s){s.timer-=dt;if(s.timer<0){s.x=0;s.y=Math.random()*H*0.6;s.vx=9+Math.random()*7;s.vy=0.5+Math.random()*1.5;s.alpha=1;s.timer=120+Math.random()*180;}if(s.alpha>0){s.x+=s.vx*dt;s.y+=s.vy*dt;s.alpha=Math.max(0,s.alpha-0.015*dt);var len=60;ctx.save();ctx.globalAlpha=s.alpha;var sg=ctx.createLinearGradient(s.x-len,s.y,s.x,s.y);sg.addColorStop(0,'transparent');sg.addColorStop(1,'rgba(220,200,255,.9)');ctx.strokeStyle=sg;ctx.lineWidth=1.5;ctx.beginPath();ctx.moveTo(s.x-len,s.y);ctx.lineTo(s.x,s.y);ctx.stroke();ctx.restore();}});for(var i=0;i<LINES.length;i++){var x=LINES[i],y=LINES[i];var p=0.7+0.3*Math.sin(tc*1.4+i*0.7);ctx.save();ctx.strokeStyle='rgba(140,80,255,'+(0.25*p)+')';ctx.lineWidth=10;ctx.shadowColor='rgba(160,80,255,.6)';ctx.shadowBlur=25;ctx.beginPath();ctx.moveTo(x,0);ctx.lineTo(x,H);ctx.stroke();ctx.restore();ctx.save();ctx.strokeStyle='rgba(180,110,255,'+(0.55*p)+')';ctx.lineWidth=4;ctx.shadowColor='rgba(200,120,255,.9)';ctx.shadowBlur=15;ctx.beginPath();ctx.moveTo(x,0);ctx.lineTo(x,H);ctx.stroke();ctx.restore();ctx.save();ctx.strokeStyle='rgba(230,200,255,'+(0.9*p)+')';ctx.lineWidth=1.5;ctx.shadowColor='rgba(255,255,255,1)';ctx.shadowBlur=6;ctx.beginPath();ctx.moveTo(x,0);ctx.lineTo(x,H);ctx.stroke();ctx.restore();ctx.save();ctx.strokeStyle='rgba(80,140,255,'+(0.25*p)+')';ctx.lineWidth=10;ctx.shadowColor='rgba(80,160,255,.6)';ctx.shadowBlur=25;ctx.beginPath();ctx.moveTo(0,y);ctx.lineTo(W,y);ctx.stroke();ctx.restore();ctx.save();ctx.strokeStyle='rgba(100,170,255,'+(0.55*p)+')';ctx.lineWidth=4;ctx.shadowColor='rgba(120,200,255,.9)';ctx.shadowBlur=15;ctx.beginPath();ctx.moveTo(0,y);ctx.lineTo(W,y);ctx.stroke();ctx.restore();ctx.save();ctx.strokeStyle='rgba(200,230,255,'+(0.9*p)+')';ctx.lineWidth=1.5;ctx.shadowColor='rgba(255,255,255,1)';ctx.shadowBlur=6;ctx.beginPath();ctx.moveTo(0,y);ctx.lineTo(W,y);ctx.stroke();ctx.restore();}for(var rr2=0;rr2<LINES.length;rr2++)for(var ci=0;ci<LINES.length;ci++){var nx=LINES[ci],ny=LINES[rr2];var fl=0.5+0.5*Math.abs(Math.sin(tc*2.2+(rr2*6+ci)*0.9));ctx.save();ctx.strokeStyle='rgba(200,160,255,'+(0.6*fl)+')';ctx.lineWidth=1;ctx.shadowColor='rgba(200,160,255,.8)';ctx.shadowBlur=14*fl;ctx.beginPath();ctx.arc(nx,ny,7*fl,0,Math.PI*2);ctx.stroke();ctx.fillStyle='rgba(255,240,255,'+(0.9*fl)+')';ctx.shadowColor='rgba(255,255,255,1)';ctx.shadowBlur=12*fl;ctx.beginPath();ctx.arc(nx,ny,2.5,0,Math.PI*2);ctx.fill();ctx.restore();}}`
