      draw: `function(ctx,tc,dt,W,H,LINES,CS){ctx.clearRect(0,0,W,H);ctx.fillStyle='#140300';ctx.fillRect(0,0,W,H);var og=ctx.createLinearGradient(0,0,W,H);og.addColorStop(0,'rgba(255,50,0,0)');og.addColorStop(0.4,'rgba(255,50,0,0)');og.addColorStop(1,'rgba(255,50,0,0.04)');ctx.fillStyle=og;ctx.fillRect(0,0,W,H);var bgl=ctx.createRadialGradient(W*0.5,H,0,W*0.5,H,H*0.7);bgl.addColorStop(0,'rgba(204,0,0,0.12)');bgl.addColorStop(1,'transparent');ctx.fillStyle=bgl;ctx.fillRect(0,0,W,H);embers.forEach(function(e){e.y-=e.vy*dt;var tr=(e.startY-e.y)/(H*0.6);if(tr>=1){e.y=e.startY;e.x=Math.random()*W;tr=0;}var op=e.op*(1-tr);ctx.save();ctx.globalAlpha=op;ctx.fillStyle='rgba(255,'+e.g+',0,0.8)';ctx.shadowColor='rgba(255,90,0,0.9)';ctx.shadowBlur=6;ctx.beginPath();ctx.arc(e.x,e.y,e.size,0,Math.PI*2);ctx.fill();ctx.restore();});ctx.save();ctx.strokeStyle='rgba(255,50,0,0.12)';ctx.lineWidth=1;for(var i=0;i<LINES.length;i++){var x=LINES[i];ctx.beginPath();ctx.moveTo(x,0);ctx.lineTo(x,H);ctx.stroke();ctx.beginPath();ctx.moveTo(0,x);ctx.lineTo(W,x);ctx.stroke();}ctx.restore();}`
