      draw: `function(ctx,tc,dt,W,H,LINES,CS){ctx.clearRect(0,0,W,H);var sky=ctx.createLinearGradient(0,0,0,H*0.55);sky.addColorStop(0,'#0a002a');sky.addColorStop(0.3,'#1a004a');sky.addColorStop(0.6,'#3a0060');sky.addColorStop(0.85,'#8b0050');sky.addColorStop(1,'#cc2060');ctx.fillStyle=sky;ctx.fillRect(0,0,W,H*0.55);var floor=ctx.createLinearGradient(0,H*0.55,0,H);floor.addColorStop(0,'#1a001a');floor.addColorStop(0.5,'#0a000f');floor.addColorStop(1,'#050008');ctx.fillStyle=floor;ctx.fillRect(0,H*0.55,W,H*0.45);stars.forEach(function(s){s.phase+=s.spd;var br=0.3+0.7*Math.abs(Math.sin(s.phase));ctx.save();ctx.globalAlpha=br*0.9;ctx.fillStyle=s.col;ctx.shadowColor=s.col;ctx.shadowBlur=s.r>1?6:2;ctx.beginPath();ctx.arc(s.x,s.y,s.r,0,Math.PI*2);ctx.fill();ctx.restore();});var hg=ctx.createLinearGradient(0,H*0.45,0,H*0.65);hg.addColorStop(0,'transparent');hg.addColorStop(0.4,'rgba(255,80,160,'+(0.35+0.1*Math.sin(tc*0.5))+')');hg.addColorStop(0.6,'rgba(180,0,80,'+(0.2+0.08*Math.sin(tc*0.5))+')');hg.addColorStop(1,'transparent');ctx.fillStyle=hg;ctx.fillRect(0,H*0.45,W,H*0.2);var pulse=0.92+0.08*Math.sin(tc*1.2);for(var ring=8;ring>=1;ring--){var rr=sun.r*(ring*0.22)*pulse;var sg=ctx.createRadialGradient(sun.cx,sun.cy,0,sun.cx,sun.cy,rr);sg.addColorStop(0,'rgba(255,120,0,'+(0.12*ring)+')');sg.addColorStop(0.5,'rgba(255,60,80,'+(0.06*ring)+')');sg.addColorStop(1,'transparent');ctx.fillStyle=sg;ctx.beginPath();ctx.arc(sun.cx,sun.cy,rr,0,Math.PI*2);ctx.fill();}ctx.save();var sd=ctx.createRadialGradient(sun.cx,sun.cy,0,sun.cx,sun.cy,sun.r*pulse);sd.addColorStop(0,'rgba(255,200,80,1)');sd.addColorStop(0.4,'rgba(255,100,60,.95)');sd.addColorStop(0.7,'rgba(255,40,80,.9)');sd.addColorStop(1,'rgba(220,0,60,.7)');ctx.fillStyle=sd;ctx.shadowColor='rgba(255,80,100,.8)';ctx.shadowBlur=40;ctx.beginPath();ctx.arc(sun.cx,sun.cy,sun.r*pulse,0,Math.PI*2);ctx.fill();ctx.restore();ctx.save();ctx.globalCompositeOperation='destination-out';for(var sl=0;sl<8;sl++){var syl=sun.cy-sun.r*0.75+sl*sun.r*0.22+Math.sin(tc*0.4)*3;ctx.fillStyle='rgba(0,0,0,.18)';ctx.fillRect(sun.cx-sun.r,syl,sun.r*2,sun.r*0.1);}ctx.globalCompositeOperation='source-over';ctx.restore();ctx.fillStyle='rgba(0,0,0,.9)';neonCities.forEach(function(c){ctx.fillRect(c.x,c.y,c.w,c.h);});neonCities.forEach(function(c){for(var wy=c.y+4;wy<c.y+c.h-4;wy+=8){for(var wx=c.x+3;wx<c.x+c.w-3;wx+=7){var wbr=0.3+0.7*Math.abs(Math.sin(tc*2+(wx+wy)*0.1));ctx.save();ctx.globalAlpha=wbr*0.8;ctx.fillStyle=Math.random()>0.5?'#ff44cc':'#44aaff';ctx.fillRect(wx,wy,3,3);ctx.restore();}}});var hor=H*0.55;var vpx=W/2;var maxLines=12;ctx.save();ctx.strokeStyle='rgba(255,0,160,.28)';ctx.lineWidth=1;for(var i2=-maxLines;i2<=maxLines;i2++){var sx=W/2+i2*(W*0.06),sy2=H;var ex=vpx+(sx-vpx)*0.02,ey=hor;ctx.beginPath();ctx.moveTo(sx,sy2);ctx.lineTo(ex,ey);ctx.stroke();}for(var j2=1;j2<=10;j2++){var prog=j2/10;var alpha=0.06+0.22*(1-prog);var yy=hor+((H-hor)*(1-Math.pow(1-prog,0.7)));ctx.strokeStyle='rgba(255,0,200,'+alpha+')';ctx.beginPath();ctx.moveTo(0,yy);ctx.lineTo(W,yy);ctx.stroke();}ctx.restore();for(var i=0;i<LINES.length;i++){var x=LINES[i],y=LINES[i];var p=0.65+0.35*Math.sin(tc*1.8+i*0.85);ctx.save();ctx.strokeStyle='rgba(255,0,180,.07)';ctx.lineWidth=18;ctx.beginPath();ctx.moveTo(x,0);ctx.lineTo(x,H);ctx.stroke();ctx.restore();ctx.save();ctx.strokeStyle='rgba(255,20,180,'+(0.2*p)+')';ctx.lineWidth=9;ctx.shadowColor='rgba(255,0,200,.8)';ctx.shadowBlur=26;ctx.beginPath();ctx.moveTo(x,0);ctx.lineTo(x,H);ctx.stroke();ctx.restore();ctx.save();ctx.strokeStyle='rgba(255,40,200,'+(0.76*p)+')';ctx.lineWidth=4;ctx.shadowColor='rgba(255,0,220,1)';ctx.shadowBlur=22;ctx.beginPath();ctx.moveTo(x,0);ctx.lineTo(x,H);ctx.stroke();ctx.restore();ctx.save();ctx.strokeStyle='rgba(255,200,240,'+(0.92*p)+')';ctx.lineWidth=1.2;ctx.shadowColor='rgba(255,255,255,.9)';ctx.shadowBlur=9;ctx.beginPath();ctx.moveTo(x,0);ctx.lineTo(x,H);ctx.stroke();ctx.restore();ctx.save();ctx.strokeStyle='rgba(0,220,255,.06)';ctx.lineWidth=18;ctx.beginPath();ctx.moveTo(0,y);ctx.lineTo(W,y);ctx.stroke();ctx.restore();ctx.save();ctx.strokeStyle='rgba(0,200,255,'+(0.18*p)+')';ctx.lineWidth=9;ctx.shadowColor='rgba(0,220,255,.8)';ctx.shadowBlur=26;ctx.beginPath();ctx.moveTo(0,y);ctx.lineTo(W,y);ctx.stroke();ctx.restore();ctx.save();ctx.strokeStyle='rgba(0,230,255,'+(0.74*p)+')';ctx.lineWidth=4;ctx.shadowColor='rgba(0,240,255,1)';ctx.shadowBlur=22;ctx.beginPath();ctx.moveTo(0,y);ctx.lineTo(W,y);ctx.stroke();ctx.restore();ctx.save();ctx.strokeStyle='rgba(200,250,255,'+(0.92*p)+')';ctx.lineWidth=1.2;ctx.shadowColor='rgba(255,255,255,.9)';ctx.shadowBlur=9;ctx.beginPath();ctx.moveTo(0,y);ctx.lineTo(W,y);ctx.stroke();ctx.restore();}}`
